tests:
test({ sr: 'deli po zarezima i čisti razmake', en: 'splits by commas and trims spaces' }, () => {
  expect(splitList('a, b,c')).toEqual(['a', 'b', 'c']);
});
test({ sr: 'bez zareza ostaje jedna stavka', en: 'without commas there is one item' }, () => {
  expect(splitList('  x  ')).toEqual(['x']);
});
test({ sr: 'prazan tekst daje prazan niz', en: 'empty text gives an empty array' }, () => {
  expect(splitList('')).toEqual([]);
});

hiddenTests:
test('empty items between two commas are skipped', () => {
  expect(splitList('a,,b')).toEqual(['a', 'b']);
});
test('only spaces give an empty array', () => {
  expect(splitList(' , ')).toEqual([]);
});
test('a longer list', () => {
  expect(splitList('one, two ,three')).toEqual(['one', 'two', 'three']);
});

solutions.code:
function splitList(text) {
  const result = [];
  for (const part of text.split(',')) {
    const item = part.trim();
    if (item !== '') result.push(item);
  }
  return result;
}
